-- Rattachement : même id ET même classe, par sécurité
update contenu_questions q
set notion_id = n.id
from tmp_classement t
join contenu_notions n on n.code = t.notion
where q.id = t.question_id and q.classe = t.classe;

-- Contrôle : si une question n'a pas trouvé sa notion, on annule tout
do $$
declare v_reste integer;
begin
	select count(*) into v_reste from contenu_questions where notion_id is null;
	if v_reste > 0 then
		raise exception 'ANNULÉ : % question(s) sans notion (ajoutées ou modifiées depuis la migration ?)', v_reste;
	end if;
end $$;

-- Désormais, toute nouvelle question doit avoir une notion
alter table contenu_questions alter column notion_id set not null;

commit;
